        for (int c = 0; c < numCourses; c++) if (indeg[c] == 0) heap.offer(c);
        int[] order = new int[numCourses];
        int k = 0;
        while (!heap.isEmpty()) {
            int course = heap.poll();
            order[k++] = course;
            for (int nxt : adj.get(course)) if (--indeg[nxt] == 0) heap.offer(nxt);
        }
        return k == numCourses ? order : new int[0];
    }
}

