import "container/heap"

type courseHeap []int

func (h courseHeap) Len() int           { return len(h) }
func (h courseHeap) Less(i, j int) bool { return h[i] < h[j] }
func (h courseHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *courseHeap) Push(x any)        { *h = append(*h, x.(int)) }
func (h *courseHeap) Pop() any {
    old := *h
    x := old[len(old)-1]
    *h = old[:len(old)-1]
    return x
}

func smallestCourseOrder(numCourses int, prerequisites [][]int) []int {
    adj := make([][]int, numCourses)
    indeg := make([]int, numCourses)
    for _, p := range prerequisites {
        adj[p[1]] = append(adj[p[1]], p[0])
        indeg[p[0]]++
    }
    h := &courseHeap{}
    for c := 0; c < numCourses; c++ {
        if indeg[c] == 0 {
            heap.Push(h, c)
        }
    }
    order := []int{}
    for h.Len() > 0 {
        course := heap.Pop(h).(int)
        order = append(order, course)
        for _, nxt := range adj[course] {
            indeg[nxt]--
            if indeg[nxt] == 0 {
                heap.Push(h, nxt)
            }
        }
    }
    if len(order) != numCourses {
        return []int{}
    }
    return order
}

