from collections import deque

def checkIfPrerequisite(numCourses, prerequisites, queries):
    adj = [[] for _ in range(numCourses)]
    for a, b in prerequisites:
        adj[b].append(a)

    def reaches(u, v):
        seen = {u}
        queue = deque([u])
        while queue:
            node = queue.popleft()
            if node == v:
                return True
            for nxt in adj[node]:
                if nxt not in seen:
                    seen.add(nxt)
                    queue.append(nxt)
        return False

    return [reaches(u, v) for u, v in queries]

