import java.util.*;

class Solution {
    public boolean canFinish(int numCourses, int[][] prerequisites) {
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < numCourses; i++) graph.add(new ArrayList<>());
        for (int[] p : prerequisites) graph.get(p[0]).add(p[1]);
        int[] state = new int[numCourses]; // 0 unvisited, 1 visiting, 2 visited
        for (int i = 0; i < numCourses; i++) {
            if (!dfs(i, graph, state)) return false;
        }
        return true;
    }

    private boolean dfs(int node, List<List<Integer>> graph, int[] state) {
        if (state[node] == 1) return false; // back edge: cycle
        if (state[node] == 2) return true;
        state[node] = 1;
        for (int next : graph.get(node)) {
            if (!dfs(next, graph, state)) return false;
        }
        state[node] = 2;
        return true;
    }
}

