class Solution {
public:
    bool canFinish(int numCourses, vector<vector<int>>& prerequisites) {
        vector<vector<int>> graph(numCourses);
        for (auto& p : prerequisites) graph[p[0]].push_back(p[1]);
        vector<int> state(numCourses, 0); // 0 unvisited, 1 visiting, 2 visited
        for (int i = 0; i < numCourses; i++) {
            if (!dfs(i, graph, state)) return false;
        }
        return true;
    }

private:
    bool dfs(int node, vector<vector<int>>& graph, vector<int>& state) {
        if (state[node] == 1) return false; // back edge: cycle
        if (state[node] == 2) return true;
        state[node] = 1;
        for (int next : graph[node]) {
            if (!dfs(next, graph, state)) return false;
        }
        state[node] = 2;
        return true;
    }
};

